"use client"

import * as React from "react"
import { FileText, Layers3, Mail, Paperclip } from "lucide-react"

import { cn } from "@/lib/utils"

import { useEmailInlineResourceUrls } from "./email-viewer-inline-resources"
import {
  buildMimeTree,
  deriveEmailInlineResourceScope,
  deriveEmailViewerModel,
  findMimeNodeByPath,
  getDefaultMimeSelectionPath,
} from "./email-viewer-model"
import type {
  EmailAddress,
  EmailContentModel,
  EmailHeaderModel,
  EmailSidebarItem,
  EmailSidebarModel,
  EmailViewerMessage,
  EmailViewerModel,
  EmailViewerProps,
  EmailViewerProviderProps,
  MimePartNode,
  MimePartPath,
} from "./email-viewer-types"
import { FileThumbnail } from "./file-thumbnail"
import { FileViewer } from "./file-viewer"
import {
  ViewerBody,
  ViewerHeader,
  ViewerRoot,
  ViewerSidebar,
  ViewerSidebarTrigger,
  ViewerSurface,
} from "./viewer"

export type {
  EmailAddress,
  EmailAttachmentSidebarItem,
  EmailBodySelectionPolicy,
  EmailBodySidebarItem,
  EmailContentEmpty,
  EmailContentEmptyReason,
  EmailContentFile,
  EmailContentModel,
  EmailContentNestedMessage,
  EmailFilePayload,
  EmailHeaderModel,
  EmailInlineResource,
  EmailInlineResourceKey,
  EmailInlineResourceScope,
  EmailSidebarItemBase,
  EmailSidebarItem,
  EmailSidebarModel,
  EmailSidebarSection,
  EmailSidebarThumbnailModel,
  EmailViewerMessage,
  EmailViewerModel,
  EmailViewerProviderProps,
  EmailViewerProps,
  MimeHeader,
  MimeMessage,
  MimeMessageScope,
  MimePart,
  MimePartDisposition,
  MimePartFacts,
  MimePartKind,
  MimePartNode,
  MimePartPath,
  MimePreviewPolicy,
} from "./email-viewer-types"

export {
  buildMimeTree,
  categoryForMimeNode,
  createMimeMessageScope,
  DEFAULT_EMAIL_BODY_SELECTION_POLICY,
  deriveEmailContentModel,
  deriveEmailHeaderModel,
  deriveEmailInlineResourceScope,
  deriveEmailSidebarModel,
  deriveEmailViewerModel,
  findMimeNodeByPath,
  getDefaultMimeSelectionPath,
  getInlineResourceScope,
  inlineResourceKeyToString,
  isAttachmentNode,
  isInlineResourceNode,
  isMessageNode,
  isMultipartNode,
  isRenderableNode,
  normalizeContentId,
  normalizeContentLocation,
  pathsEqual,
  replaceCidUrls,
  replaceInlineResourceUrls,
} from "./email-viewer-model"

const DEFAULT_MAX_NESTED_MESSAGE_DEPTH = 8

type EmailViewerContextValue = {
  model: EmailViewerModel
  selectPart: (node: MimePartNode) => void
}

type EmailViewerProviderInternalProps = EmailViewerProviderProps & {
  nestedMessageDepth?: number
}

type EmailViewerInternalProps = EmailViewerProps & {
  nestedMessageDepth?: number
}

type EmailViewerChromeProps = Pick<EmailViewerInternalProps, "bare" | "className">

const EmailViewerContext = React.createContext<EmailViewerContextValue | null>(
  null
)

export function useEmailViewer() {
  const context = React.useContext(EmailViewerContext)
  if (!context) {
    throw new Error("useEmailViewer must be used within EmailViewerProvider.")
  }
  return context
}

export function useEmailHeader(): EmailHeaderModel {
  return useEmailViewer().model.header
}

export function useEmailPartsSidebar(): {
  sidebar: EmailSidebarModel
  selectPart: (node: MimePartNode) => void
} {
  const { model, selectPart } = useEmailViewer()

  return {
    sidebar: model.sidebar,
    selectPart,
  }
}

export function useEmailContent(): EmailContentModel {
  return useEmailViewer().model.content
}

export function EmailViewerProvider(props: EmailViewerProviderProps) {
  return <EmailViewerProviderInternal {...props} nestedMessageDepth={0} />
}

function EmailViewerProviderInternal({
  message,
  selectedPath,
  defaultSelectedPath,
  onSelectedPathChange,
  maxNestedMessageDepth = DEFAULT_MAX_NESTED_MESSAGE_DEPTH,
  nestedMessageDepth = 0,
  children,
}: EmailViewerProviderInternalProps) {
  const rootNode = React.useMemo(
    () => buildMimeTree(message.root),
    [message.root]
  )
  const defaultPath = React.useMemo(
    () =>
      defaultSelectedPath && findMimeNodeByPath(rootNode, defaultSelectedPath)
        ? defaultSelectedPath
        : getDefaultMimeSelectionPath(rootNode),
    [defaultSelectedPath, rootNode]
  )
  const [internalSelectedPath, setInternalSelectedPath] =
    React.useState<MimePartPath>(defaultPath)
  const controlled = selectedPath !== undefined
  const activePath = controlled
    ? (selectedPath ?? defaultPath)
    : internalSelectedPath
  const selectedNode =
    findMimeNodeByPath(rootNode, activePath) ??
    findMimeNodeByPath(rootNode, defaultPath) ??
    rootNode
  const inlineResourceScope = React.useMemo(
    () => deriveEmailInlineResourceScope(rootNode, selectedNode),
    [rootNode, selectedNode]
  )
  const inlineResourceUrls = useEmailInlineResourceUrls(inlineResourceScope)

  React.useEffect(() => {
    if (controlled) return
    if (findMimeNodeByPath(rootNode, internalSelectedPath)) return
    setInternalSelectedPath(defaultPath)
  }, [controlled, defaultPath, internalSelectedPath, rootNode])

  const selectPart = React.useCallback(
    (node: MimePartNode) => {
      if (!controlled) setInternalSelectedPath(node.path)
      onSelectedPathChange?.(node.path, node)
    },
    [controlled, onSelectedPathChange]
  )
  const model = React.useMemo(
    () =>
      deriveEmailViewerModel({
        inlineResourceUrls,
        maxNestedMessageDepth,
        message,
        nestedMessageDepth,
        rootNode,
        selectedNode,
      }),
    [
      inlineResourceUrls,
      maxNestedMessageDepth,
      message,
      nestedMessageDepth,
      rootNode,
      selectedNode,
    ]
  )
  const value = React.useMemo<EmailViewerContextValue>(
    () => ({ model, selectPart }),
    [model, selectPart]
  )

  return (
    <EmailViewerContext.Provider value={value}>
      {children}
    </EmailViewerContext.Provider>
  )
}

export function EmailViewer(props: EmailViewerProps) {
  return <EmailViewerInternal {...props} nestedMessageDepth={0} />
}

function EmailViewerInternal({
  message,
  selectedPath,
  defaultSelectedPath,
  onSelectedPathChange,
  maxNestedMessageDepth,
  nestedMessageDepth = 0,
  className,
  bare = false,
}: EmailViewerInternalProps) {
  if (nestedMessageDepth === 0) {
    return (
      <EmailViewerProvider
        message={message}
        selectedPath={selectedPath}
        defaultSelectedPath={defaultSelectedPath}
        onSelectedPathChange={onSelectedPathChange}
        maxNestedMessageDepth={maxNestedMessageDepth}
      >
        <EmailViewerChrome bare={bare} className={className} />
      </EmailViewerProvider>
    )
  }

  return (
    <EmailViewerProviderInternal
      message={message}
      selectedPath={selectedPath}
      defaultSelectedPath={defaultSelectedPath}
      onSelectedPathChange={onSelectedPathChange}
      maxNestedMessageDepth={maxNestedMessageDepth}
      nestedMessageDepth={nestedMessageDepth}
    >
      <EmailViewerChrome bare={bare} className={className} />
    </EmailViewerProviderInternal>
  )
}

function EmailViewerChrome({ bare = false, className }: EmailViewerChromeProps) {
  return (
    <div data-slot="email-viewer" className={cn("min-h-0", className)}>
      <ViewerRoot bare={bare} defaultOpen sidebarSide="right" className="h-full">
        <EmailHeader />
        <ViewerBody className="flex-col md:flex-row">
          <ViewerSurface className="min-h-[26rem] md:min-h-0">
            <EmailContent />
          </ViewerSurface>
          <ViewerSidebar
            aria-label="Email parts"
            width="19rem"
            className="border-t md:border-t-0 md:border-l"
          >
            <EmailPartsSidebar />
          </ViewerSidebar>
        </ViewerBody>
      </ViewerRoot>
    </div>
  )
}

export function EmailHeader() {
  return <MimeMessageHeader header={useEmailHeader()} />
}

export function EmailPartsSidebar() {
  const { sidebar, selectPart } = useEmailPartsSidebar()

  return <MimePartSidebar sidebar={sidebar} onSelectPart={selectPart} />
}

export function EmailContent() {
  const content = useEmailContent()

  if (content.kind === "nested-message") {
    return (
      <EmailViewerInternal
        bare
        className="h-full"
        message={content.message}
        maxNestedMessageDepth={content.maxNestedMessageDepth}
        nestedMessageDepth={content.nestedMessageDepth}
      />
    )
  }

  if (content.kind === "empty") {
    return (
      <div className="flex size-full items-center justify-center px-6 text-center text-sm text-muted-foreground">
        {content.message}
      </div>
    )
  }

  return (
    <FileViewer
      key={content.node.path.join("/")}
      source={content.file.source}
      as={content.file.category}
      bare
      className="size-full min-h-0"
    />
  )
}

function MimeMessageHeader({ header }: { header: EmailHeaderModel }) {
  const from = formatEmailAddresses(header.from)
  const to = formatEmailAddresses(header.to)

  return (
    <ViewerHeader className="px-3 py-2">
      <div
        data-slot="email-message-header"
        className="flex min-h-0 flex-col gap-1"
      >
        <div className="flex min-w-0 items-center gap-2">
          <Mail className="size-4 flex-shrink-0 text-muted-foreground" />
          <h2 className="min-w-0 flex-1 truncate text-sm font-medium">
            {header.subject}
          </h2>
          <ViewerSidebarTrigger className="-mr-1" />
        </div>
        <div className="flex min-w-0 flex-wrap gap-x-3 gap-y-1 pl-6 text-xs text-muted-foreground">
          {from ? <span className="min-w-0 truncate">From {from}</span> : null}
          {to ? <span className="min-w-0 truncate">To {to}</span> : null}
          {header.sentAt ? (
            <span className="tabular-nums">{header.sentAt}</span>
          ) : null}
        </div>
      </div>
    </ViewerHeader>
  )
}

function MimePartSidebar({
  sidebar,
  onSelectPart,
  className,
}: {
  sidebar: EmailSidebarModel
  onSelectPart: (node: MimePartNode) => void
  className?: string
}) {
  return (
    <div
      data-slot="mime-part-sidebar"
      className={cn(
        "flex h-full min-h-0 flex-col bg-background text-foreground",
        className
      )}
    >
      <div className="flex-shrink-0 border-b px-3 py-2">
        <div className="flex h-6 items-center gap-2 text-xs font-medium">
          <Paperclip className="size-3.5 text-muted-foreground" />
          <span>
            {sidebar.attachmentCount} attachment
            {sidebar.attachmentCount === 1 ? "" : "s"}
          </span>
        </div>
      </div>
      <div className="min-h-0 flex-1 space-y-2 overflow-auto p-2">
        {sidebar.sections.map((section) => (
          <MimePartSidebarSection key={section.id} title={section.title}>
            {section.items.length === 0 ? (
              section.emptyLabel ? (
                <p className="px-2 py-3 text-xs text-muted-foreground">
                  {section.emptyLabel}
                </p>
              ) : null
            ) : (
              <ul className="flex flex-col gap-1">
                {section.items.map((item) => (
                  <MimePartSidebarItem
                    key={item.id}
                    item={item}
                    onSelectPart={onSelectPart}
                  />
                ))}
              </ul>
            )}
          </MimePartSidebarSection>
        ))}
      </div>
    </div>
  )
}

function formatEmailAddresses(addresses: readonly EmailAddress[]) {
  return addresses.map((address) => address.display).join(", ") || null
}

function MimePartSidebarSection({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  const titleId = React.useId()

  return (
    <section
      aria-labelledby={titleId}
      data-slot="mime-part-sidebar-section"
      className="min-w-0"
    >
      <h3
        id={titleId}
        className="flex h-8 shrink-0 items-center px-2 text-xs font-medium text-muted-foreground"
      >
        {title}
      </h3>
      {children}
    </section>
  )
}

function MimePartSidebarItem({
  item,
  onSelectPart,
}: {
  item: EmailSidebarItem
  onSelectPart: (node: MimePartNode) => void
}) {
  return (
    <li data-slot="mime-part-sidebar-item">
      <button
        type="button"
        aria-current={item.isSelected ? "page" : undefined}
        aria-label={`${item.title} ${item.description}`}
        data-selected={item.isSelected ? "true" : "false"}
        className={cn(
          "flex h-auto w-full items-center gap-3 overflow-hidden rounded-lg border p-2 text-left text-sm outline-hidden transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring active:bg-accent",
          item.isSelected
            ? "border-border bg-accent text-accent-foreground"
            : "border-transparent"
        )}
        onClick={() => onSelectPart(item.node)}
      >
        <SidebarItemThumbnail item={item} />
        <span className="flex min-w-0 flex-1 flex-col gap-1">
          <span className="truncate text-sm font-medium">{item.title}</span>
          <span
            className={cn(
              "truncate text-xs",
              item.isSelected
                ? "text-accent-foreground/80"
                : "text-muted-foreground"
            )}
          >
            {item.description}
          </span>
        </span>
      </button>
    </li>
  )
}

function SidebarItemThumbnail({ item }: { item: EmailSidebarItem }) {
  if (item.thumbnail.kind === "file") {
    return (
      <FileThumbnail
        source={item.thumbnail.source}
        presentation="decorative"
        className="size-12 flex-shrink-0"
        previewAspectRatio={item.thumbnail.aspectRatio}
      />
    )
  }

  return (
    <span
      className={cn(
        "flex size-12 flex-shrink-0 items-center justify-center rounded-md bg-muted/60",
        item.isSelected ? "text-accent-foreground" : "text-muted-foreground"
      )}
    >
      <PartIcon icon={item.thumbnail.icon} className="size-4" />
    </span>
  )
}

function PartIcon({
  icon,
  className,
}: {
  icon: "file" | "layers" | "mail" | "paperclip"
  className?: string
}) {
  if (icon === "layers") return <Layers3 className={className} aria-hidden />
  if (icon === "mail") return <Mail className={className} aria-hidden />
  if (icon === "paperclip") {
    return <Paperclip className={className} aria-hidden />
  }
  return <FileText className={className} aria-hidden />
}

"use client"

import * as React from "react"
import { PanelLeft, PanelRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button, type ButtonProps } from "@/components/ui/button"

export type ViewerRootProps = React.ComponentProps<"div"> & {
  bare?: boolean
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
  mode?: ViewerSidebarRequestedMode
  inlineBreakpoint?: number
  sidebarSide?: ViewerSidebarSide
  sidebarCollapsible?: ViewerSidebarCollapsible
  shortcut?: string | null
}

export type ViewerSidebarMode = "inline" | "overlay"
export type ViewerSidebarRequestedMode = "auto" | ViewerSidebarMode
export type ViewerSidebarState = "expanded" | "collapsed"
export type ViewerSidebarContextValue = {
  state: ViewerSidebarState
  open: boolean
  setOpen: (value: boolean | ((open: boolean) => boolean)) => void
  toggleSidebar: () => void
  canToggleSidebar: boolean
  mode: ViewerSidebarMode
}

type ViewerSidebarSide = "left" | "right"
type ViewerSidebarCollapsible = "offcanvas" | "none"
type ViewerSidebarRegistration = {
  collapsible: ViewerSidebarCollapsible
  element: HTMLElement
  id: string
  instanceId: string
  side: ViewerSidebarSide
  width: string
}

type ViewerSidebarRegistrationContextValue = {
  defaultSidebarCollapsible: ViewerSidebarCollapsible
  defaultSidebarSide: ViewerSidebarSide
  hasSidebar: boolean
  sidebarState: ViewerSidebarContextValue
  registerSidebar: (registration: ViewerSidebarRegistration) => () => void
  rootId: string
  sidebarId: string
  sidebarSide: ViewerSidebarSide
  setLastTriggerElement: (element: HTMLElement | null) => void
}

const VIEWER_SIDEBAR_INLINE_BREAKPOINT = 768
const VIEWER_SIDEBAR_MODE_HYSTERESIS = 16
const VIEWER_SIDEBAR_WIDTH = "10rem"

const ViewerSidebarStateContext =
  React.createContext<ViewerSidebarContextValue | null>(null)
const ViewerSidebarRegistrationContext =
  React.createContext<ViewerSidebarRegistrationContextValue | null>(null)

function resolveSidebarMode({
  requestedMode,
  width,
  inlineBreakpoint,
}: {
  requestedMode: ViewerSidebarRequestedMode
  width: number | null
  inlineBreakpoint: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (width === null) return "overlay"
  return width >= inlineBreakpoint ? "inline" : "overlay"
}

function resolveMeasuredSidebarMode({
  currentMode,
  hasMeasured,
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  currentMode: ViewerSidebarMode
  hasMeasured: boolean
  inlineBreakpoint: number
  requestedMode: ViewerSidebarRequestedMode
  width: number
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode
  if (!hasMeasured) {
    return width >= inlineBreakpoint ? "inline" : "overlay"
  }

  if (currentMode === "inline") {
    return width < inlineBreakpoint - VIEWER_SIDEBAR_MODE_HYSTERESIS
      ? "overlay"
      : "inline"
  }

  return width > inlineBreakpoint + VIEWER_SIDEBAR_MODE_HYSTERESIS
    ? "inline"
    : "overlay"
}

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

function isAriaDisabled(value: unknown): boolean {
  return value === true || value === "true"
}

function matchesShortcut(
  event: React.KeyboardEvent,
  shortcut: string | null | undefined
): boolean {
  if (!shortcut) return false

  const parts = shortcut
    .toLowerCase()
    .split("+")
    .map((part) => part.trim())
    .filter(Boolean)
  const key = parts.at(-1)
  if (!key) return false

  const wantsMod = parts.includes("mod")
  const wantsCtrl = parts.includes("ctrl")
  const wantsMeta = parts.includes("meta") || parts.includes("cmd")
  const wantsAlt = parts.includes("alt")
  const wantsShift = parts.includes("shift")

  if (wantsMod && !event.ctrlKey && !event.metaKey) return false
  if (!wantsMod && event.ctrlKey !== wantsCtrl) return false
  if (!wantsMod && event.metaKey !== wantsMeta) return false
  if (event.altKey !== wantsAlt) return false
  if (event.shiftKey !== wantsShift) return false

  return event.key.toLowerCase() === key
}

export function useViewerSidebar(): ViewerSidebarContextValue {
  const context = React.useContext(ViewerSidebarStateContext)
  if (!context) {
    throw new Error("useViewerSidebar must be used within a ViewerRoot.")
  }
  return context
}

export function useOptionalViewerSidebar(): ViewerSidebarContextValue | null {
  return React.useContext(ViewerSidebarStateContext)
}

function useViewerSidebarRegistrationContext(
  consumer: string
): ViewerSidebarRegistrationContextValue {
  const context = React.useContext(ViewerSidebarRegistrationContext)
  if (!context) {
    throw new Error(`${consumer} must be used within a ViewerRoot.`)
  }
  return context
}

export function ViewerRoot({
  bare = false,
  className,
  style,
  defaultOpen = false,
  open: openProp,
  onOpenChange,
  onKeyDown,
  mode = "inline",
  inlineBreakpoint = VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  sidebarSide = "left",
  sidebarCollapsible = "offcanvas",
  shortcut = null,
  ...props
}: ViewerRootProps) {
  const rootRef = React.useRef<HTMLDivElement | null>(null)
  const reactId = React.useId()
  const rootId = `${reactId}-viewer-root`
  const fallbackSidebarId = `${reactId}-viewer-sidebar`
  const isControlled = openProp !== undefined
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const open = openProp ?? internalOpen
  const openRef = React.useRef(open)
  const hasMeasuredSidebarWidthRef = React.useRef(false)
  const lastTriggerElementRef = React.useRef<HTMLElement | null>(null)
  const registeredSidebarRef = React.useRef<ViewerSidebarRegistration | null>(
    null
  )
  const [registeredSidebar, setRegisteredSidebar] =
    React.useState<ViewerSidebarRegistration | null>(null)
  const [resolvedSidebarMode, setResolvedSidebarMode] =
    React.useState<ViewerSidebarMode>(() =>
      resolveSidebarMode({
        requestedMode: mode,
        width: null,
        inlineBreakpoint,
      })
    )

  React.useEffect(() => {
    openRef.current = open
  }, [open])

  React.useEffect(() => {
    if (mode === "auto") return
    setResolvedSidebarMode((currentMode) => {
      const nextMode = mode
      return currentMode === nextMode ? currentMode : nextMode
    })
  }, [mode])

  useIsoLayoutEffect(() => {
    const element = rootRef.current
    const ResizeObserverConstructor = globalThis.ResizeObserver
    if (!element || typeof ResizeObserverConstructor === "undefined") return
    if (mode !== "auto") {
      setResolvedSidebarMode(mode)
      return
    }

    const updateMode = () => {
      const nextWidth = element.getBoundingClientRect().width
      if (nextWidth === 0) return

      setResolvedSidebarMode((currentMode) => {
        const nextMode = resolveMeasuredSidebarMode({
          currentMode,
          hasMeasured: hasMeasuredSidebarWidthRef.current,
          requestedMode: mode,
          width: nextWidth,
          inlineBreakpoint,
        })

        hasMeasuredSidebarWidthRef.current = true
        return currentMode === nextMode ? currentMode : nextMode
      })
    }

    updateMode()

    const observer = new ResizeObserverConstructor(updateMode)
    observer.observe(element)

    return () => observer.disconnect()
  }, [inlineBreakpoint, mode])

  const setOpen = React.useCallback(
    (value: boolean | ((open: boolean) => boolean)) => {
      const previousOpen = isControlled ? open : openRef.current
      const nextOpen = typeof value === "function" ? value(previousOpen) : value

      if (nextOpen === previousOpen) {
        return
      }

      if (!isControlled) {
        openRef.current = nextOpen
        setInternalOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [isControlled, onOpenChange, open]
  )

  const registerSidebar = React.useCallback(
    (registration: ViewerSidebarRegistration) => {
      const currentRegistration = registeredSidebarRef.current

      if (
        currentRegistration &&
        currentRegistration.instanceId !== registration.instanceId
      ) {
        throw new Error(
          "ViewerRoot supports one primary ViewerSidebar. Use a nested ViewerRoot for a complete nested viewer, or put secondary content inside ViewerSurface."
        )
      }

      registeredSidebarRef.current = registration
      setRegisteredSidebar(registration)

      return () => {
        if (
          registeredSidebarRef.current?.instanceId !== registration.instanceId
        ) {
          return
        }

        registeredSidebarRef.current = null
        setRegisteredSidebar(null)
      }
    },
    []
  )

  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen)
  }, [setOpen])

  const hasSidebar = registeredSidebar !== null
  const effectiveOpen = registeredSidebar?.collapsible === "none" ? true : open
  const state: ViewerSidebarState = effectiveOpen ? "expanded" : "collapsed"
  const canToggleSidebar =
    hasSidebar && registeredSidebar.collapsible !== "none"
  const sidebarId = registeredSidebar?.id ?? fallbackSidebarId
  const resolvedSidebarSide = registeredSidebar?.side ?? sidebarSide
  const sidebarWidth = registeredSidebar?.width ?? VIEWER_SIDEBAR_WIDTH
  const setLastTriggerElement = React.useCallback(
    (element: HTMLElement | null) => {
      lastTriggerElementRef.current = element
    },
    []
  )

  React.useEffect(() => {
    if (
      !open ||
      !canToggleSidebar ||
      resolvedSidebarMode !== "overlay" ||
      typeof document === "undefined"
    ) {
      return
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false)
        const triggerElement =
          lastTriggerElementRef.current?.isConnected === true
            ? lastTriggerElementRef.current
            : rootRef.current?.querySelector<HTMLElement>(
                "[data-viewer-sidebar-trigger]"
              )
        triggerElement?.focus()
      }
    }
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target

      if (
        target instanceof Node &&
        registeredSidebar?.element.contains(target)
      ) {
        return
      }

      if (target instanceof Element) {
        const triggerElement = target.closest<HTMLElement>(
          "[data-viewer-sidebar-trigger]"
        )
        if (triggerElement?.dataset.viewerRootId === rootId) {
          return
        }
      }

      setOpen(false)
    }

    document.addEventListener("keydown", handleKeyDown)
    document.addEventListener("pointerdown", handlePointerDown)

    return () => {
      document.removeEventListener("keydown", handleKeyDown)
      document.removeEventListener("pointerdown", handlePointerDown)
    }
  }, [
    canToggleSidebar,
    open,
    registeredSidebar,
    resolvedSidebarMode,
    rootId,
    setOpen,
  ])

  const sidebarStateContext = React.useMemo<ViewerSidebarContextValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
    ]
  )

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationContextValue>(
      () => ({
        defaultSidebarCollapsible: sidebarCollapsible,
        defaultSidebarSide: sidebarSide,
        hasSidebar,
        sidebarState: sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarSide: resolvedSidebarSide,
        setLastTriggerElement,
      }),
      [
        hasSidebar,
        sidebarCollapsible,
        resolvedSidebarSide,
        sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarSide,
        setLastTriggerElement,
      ]
    )

  return (
    <ViewerSidebarStateContext.Provider value={sidebarStateContext}>
      <ViewerSidebarRegistrationContext.Provider
        value={sidebarRegistrationContext}
      >
        <div
          ref={rootRef}
          data-slot="viewer-root"
          data-viewer-root-id={rootId}
          onKeyDown={(event) => {
            onKeyDown?.(event)
            if (
              event.defaultPrevented ||
              !canToggleSidebar ||
              !matchesShortcut(event, shortcut)
            ) {
              return
            }

            event.preventDefault()
            toggleSidebar()
          }}
          className={cn(
            "relative flex min-h-0 flex-col overflow-hidden",
            bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
            className
          )}
          style={
            {
              ...style,
              "--viewer-sidebar-width": sidebarWidth,
            } as React.CSSProperties
          }
          {...props}
        />
      </ViewerSidebarRegistrationContext.Provider>
    </ViewerSidebarStateContext.Provider>
  )
}

